+// for typed results — rawFields is only populated for unknown types — or when
+// no key matches.
+func (r *Result) rawString(keys ...string) string {
+	for _, k := range keys {
+		var s string
+		if err := json.Unmarshal(r.rawFields[k], &s); err == nil && s != "" {
+			return s
+		}
+	}
+	return ""
